def split_row(line: str):
    """Split one CSV line into fields, honoring quoted commas and quotes."""
    fields = []
    field = []
    in_quotes = False
    at_field_start = True
    i = 0

    while i < len(line):
        char = line[i]

        if in_quotes:
            if char == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(char)
        elif char == '"' and at_field_start:
            in_quotes = True
        elif char == ',':
            fields.append(''.join(field))
            field = []
            at_field_start = True
        else:
            field.append(char)
            at_field_start = False

        i += 1

    fields.append(''.join(field))
    return fields
